B.alT=new A.hb("health","\uac74\uac15 \uace0\uc9c0\xb7\uc758\ud559 \uc9c4\uc220\uc11c\uc5d0 \uc0ac\uc2e4\ub300\ub85c \uc751\ud558\uace0 \uc774\uc0c1 \uc2dc \uc989\uc2dc \uc911\ub2e8\ud558\uaca0\uc2b5\ub2c8\ub2e4.")
B.alM=new A.hb("emergency","\uc758\uc2dd \uc18c\uc2e4 \ub4f1 \uc751\uae09 \uc2dc \uad6c\uc870\xb7\uc774\uc1a1 \uc870\uce58\uc5d0 \ub3d9\uc758\ud569\ub2c8\ub2e4.")
B.Zz=s([B.alR,B.alQ,B.alT,B.r5,B.r7,B.alM,B.r6],t.OZ)
B.amn=new A.r5("freediving","\ud504\ub9ac\ub2e4\uc774\ube59 \uba74\ucc45","\ud504\ub9ac\ub2e4\uc774\ube59 \ucc45\uc784 \uba74\ucc45 \ubc0f \uc704\ud5d8 \uc778\uc9c0\xb7\uc218\uc6a9 \ub3d9\uc758\uc11c","FREEDIVING LIABILITY RELEASE AND ASSUMPTION OF RISK AGREEMENT","\ubcf8 \ub3d9\uc758\uc11c\ub294 APDI \ud504\ub9ac\ub2e4\uc774\ube59 \uad50\uc721, \ud6c8\ub828 \ubc0f \uad00\ub828 \ud65c\ub3d9\uc5d0 \ucc38\uac00\ud558\ub294 \uc0ac\ub78c\uc774 \uc228\ucc38\uae30 \uc7a0\uc218\uc758 \uc7a0\uc7ac\uc801 \uc704\ud5d8\uacfc \uc548\uc804\uc0c1 \uc758\ubb34\ub97c \ucda9\ubd84\ud788 \uc774\ud574\ud558\uace0 \uc790\ubc1c\uc801\uc73c\ub85c \ucc38\uac00\ud558\ub294\uc9c0 \ud655\uc778\ud558\uae30 \uc704\ud55c \ubb38\uc11c\uc785\ub2c8\ub2e4. \ubcf8\uc778\uc740 \uc11c\uba85\ud558\uae30 \uc804\uc5d0 \uc544\ub798 \ub0b4\uc6a9\uc744 \ucda9\ubd84\ud788 \uc77d\uace0, \uc774\ud574\ub418\uc9c0 \uc54a\ub294 \uc0ac\ud56d\uc5d0 \ub300\ud574 \uc124\uba85\uc744 \uc694\uccad\ud560 \uae30\ud68c\uac00 \uc788\uc74c\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.","\ubcf8 \ub3d9\uc758\uc11c\ub294 \ubcc4\ub3c4\uc758 \uac74\uac15\uc9c4\uc220\uc11c, \uad50\uc721\uacc4\uc57d \ubc0f \uacfc\uc815\ubcc4 \uc548\uc804\uad50\uc721 \ud655\uc778\uc11c\ub97c \ub300\uccb4\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.",B.a_N,B.Zz)
B.Zp=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc774 \uc804\ubb38\uc801\uc778 \uc7a5\ube44\uc640 \ud638\ud761 \uae30\uccb4, \ubcf5\uc7a1\ud55c \ub2e4\uc774\ube59 \uacc4\ud68d \ubc0f \uac10\uc555\uc808\ucc28\ub97c \ud3ec\ud568\ud560 \uc218 \uc788\uc73c\uba70, \uc77c\ubc18 \ub808\ud06c\ub9ac\uc5d0\uc774\uc158 \ub2e4\uc774\ube59\ubcf4\ub2e4 \uc911\ub300\ud55c \uc704\ud5d8\uc774 \uc99d\uac00\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uc704\ud5d8\uc774 \uc874\uc7ac\ud568\uc744 \uc778\uc9c0\ud569\ub2c8\ub2e4."],t.s)
B.a_U=s(["\uac10\uc555\ubcd1 \ubc0f \ub3d9\ub9e5\uac00\uc2a4\uc0c9\uc804\uc99d\uc744 \ud3ec\ud568\ud55c \uc7a0\uc218 \uad00\ub828 \uc9c8\ud658","\uc758\ubb34 \uac10\uc555\uc5d0 \ub530\ub978 \uc989\uac01\uc801\uc778 \uc218\uba74 \ubcf5\uadc0\uc758 \uc81c\ud55c","\uac10\uc555\uacc4\ud68d\uc758 \uc624\ub958 \ub610\ub294 \uacc4\ud68d \uc774\ud589 \uc2e4\ud328\uc5d0 \ub530\ub978 \uc704\ud5d8","\uc0b0\uc18c \ub3c5\uc131, \uc800\uc0b0\uc18c\uc99d, \uace0\ud0c4\uc0b0\ud608\uc99d \ubc0f \uc9c8\uc18c\ub9c8\ucde8 \ub4f1\uc758 \uc0dd\ub9ac\uc801 \uc704\ud5d8","\ud638\ud761 \uae30\uccb4\uc758 \uc885\ub958\uc640 \uc0ac\uc6a9 \uc870\uac74\uc5d0 \ub300\ud55c \ud310\ub2e8 \uc624\ub958","\ub2e4\uc911 \uc2e4\ub9b0\ub354 \ubc0f \ubcf5\uc7a1\ud55c \ud638\ud761\xb7\ubd80\ub825 \uc7a5\ube44\uc758 \uc624\uc791\ub3d9","\ud638\ud761 \uae30\uccb4 \uacf5\uae09 \ubb38\uc81c \ubc0f \uae30\uccb4 \uad00\ub9ac\uc0c1\uc758 \uc624\ub958","\uae4a\uc740 \uc218\uc2ec, \uc800\uc628, \ud574\ub958 \ubc0f \uc81c\ud55c\ub41c \uc2dc\uc57c\uc5d0 \ub530\ub978 \uc704\ud5d8","\ud300 \ubd84\ub9ac, \uc758\uc0ac\uc18c\ud1b5 \uc2e4\ud328 \ubc0f \uc218\uc911 \ube44\uc0c1\uc0c1\ud669 \ub300\uc751\uc758 \uc5b4\ub824\uc6c0","\uc7a5\uc2dc\uac04 \uc218\uc911\ud65c\ub3d9\uc5d0 \ub530\ub978 \uc2e0\uccb4\uc801\xb7\uc815\uc2e0\uc801 \ud53c\ub85c","\uc804\ubb38 \uad6c\uc870\uc2dc\uc124\uacfc \uc7ac\uc555\uce58\ub8cc\uc2dc\uc124 \uc811\uadfc\uc758 \uc9c0\uc5f0"],t.s)
B.aml=new A.dZ("\uc81c2\uc870. \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc758 \ud2b9\uc218 \uc704\ud5d8\uc5d0 \ub300\ud55c \uc778\uc9c0",B.Zp,B.a_U)
B.Z5=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc774 \uc801\uc808\ud55c \uc120\ud589 \uc790\uaca9, \uad50\uc721, \uacbd\ud5d8 \ubc0f \uc804\ubb38\uc801\uc778 \uac10\ub3c5\uc744 \uc694\uad6c\ud558\ub294 \ud65c\ub3d9\uc784\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc790\uc2e0\uc758 \uad50\uc721 \uc218\uc900\uacfc \uc790\uaca9 \ubc94\uc704\ub97c \ubc97\uc5b4\ub098\ub294 \ud65c\ub3d9\uc744 \uc218\ud589\ud558\uc9c0 \uc54a\uc73c\uba70, \ub2f4\ub2f9 \uac15\uc0ac\uc758 \uad50\uc721\uae30\uc900 \ubc0f \uc548\uc804\uc9c0\uce68\uc744 \uc900\uc218\ud558\uaca0\uc2b5\ub2c8\ub2e4.","\ud2b9\uc815 \ud14c\ud06c\ub2c8\uceec \uad50\uc721\uacfc\uc815\uc5d0 \ub4f1\ub85d\ud558\uac70\ub098 \ubcf8 \ub3d9\uc758\uc11c\uc5d0 \uc11c\uba85\ud558\uc600\ub2e4\ub294 \uc0ac\uc2e4\ub9cc\uc73c\ub85c \ud574\ub2f9 \uc218\uc911\ud65c\ub3d9\uc744 \ub3c5\ub9bd\uc801\uc73c\ub85c \uc218\ud589\ud560 \uc790\uaca9\uc774 \ubd80\uc5ec\ub418\ub294 \uac83\uc740 \uc544\ub2d8\uc744 \uc774\ud574\ud569\ub2c8\ub2e4."],t.s)
B.amh=new A.dZ("\uc81c3\uc870. \uc804\ubb38 \uad50\uc721\uacfc \ucc38\uac00 \uc790\uaca9",B.Z5,B.z)
B.XS=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub294 \ud638\ud761 \uae30\uccb4\uc758 \uc885\ub958\uc640 \uc870\uc131 \ubc0f \uc801\uc6a9 \ud658\uacbd\uc774 \uc548\uc804\uc5d0 \uc911\ub300\ud55c \uc601\ud5a5\uc744 \ubbf8\uce5c\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uc0ac\ud56d\uc774 \uc911\uc694\ud568\uc744 \uc778\uc9c0\ud569\ub2c8\ub2e4."],t.s)
B.Yg=s(["\ud638\ud761 \uae30\uccb4\uc758 \uc815\ud655\ud55c \uc2dd\ubcc4\uacfc \ubd84\uc11d","\ud638\ud761 \uae30\uccb4\uc640 \uacc4\ud68d\ub41c \uc0ac\uc6a9 \ud658\uacbd\uc758 \uc801\ud569\uc131 \ud655\uc778","\uc2e4\ub9b0\ub354 \ubc0f \ud638\ud761\uc7a5\ube44\uc5d0 \ub300\ud55c \uc810\uac80\uacfc \uad00\ub9ac","\ud638\ud761 \uae30\uccb4 \uacf5\uae09 \uc774\uc0c1\uc5d0 \ub300\ud55c \ube44\uc0c1\uacc4\ud68d","\ud300\uc6d0 \uac04 \uae30\uccb4 \ubc0f \uc7a5\ube44 \uc815\ubcf4\uc758 \uc0c1\ud638 \ud655\uc778","\uad50\uc721\uacfc\uc815\uc5d0 \uc801\ud569\ud55c \uc7a5\ube44 \uad6c\uc131\uacfc \uc0ac\uc804 \uc548\uc804\uc810\uac80"],t.s)
B.alW=new A.dZ("\uc81c4\uc870. \ud638\ud761 \uae30\uccb4 \ubc0f \ud2b9\uc218\uc7a5\ube44\uc758 \uc704\ud5d8",B.XS,B.Yg)
B.a06=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc5d0\uc11c \uc0ac\uc804\uc5d0 \uc218\ub9bd\ub41c \ub2e4\uc774\ube59 \uacc4\ud68d\uacfc \uac10\uc555 \uc758\ubb34\ub97c \uc900\uc218\ud558\ub294 \uac83\uc774 \uc911\uc694\ud568\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc218\uc911 \ud658\uacbd\uc758 \ubcc0\ud654, \uc7a5\ube44 \uc774\uc0c1 \ub610\ub294 \uac1c\uc778\uc758 \uc2e0\uccb4\uc801 \uc0c1\ud0dc\uc5d0 \ub530\ub77c \uc608\uc815\ub41c \ub2e4\uc774\ube59 \uacc4\ud68d\uc758 \ubcc0\uacbd\uc774\ub098 \uc911\ub2e8\uc774 \ud544\uc694\ud560 \uc218 \uc788\uc74c\uc744 \uc778\uc815\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2f4\ub2f9 \uac15\uc0ac\uac00 \uc2b9\uc778\ud55c \uacc4\ud68d\uacfc \ube44\uc0c1\uc808\ucc28\ub97c \uc900\uc218\ud558\uba70, \uc784\uc758\ub85c \ub2e4\uc774\ube59 \uc218\uc2ec, \uc2dc\uac04 \ub610\ub294 \ud65c\ub3d9 \ubc94\uc704\ub97c \ud655\ub300\ud558\uc9c0 \uc54a\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.am6=new A.dZ("\uc81c5\uc870. \uac10\uc555\uc808\ucc28 \ubc0f \ub2e4\uc774\ube59 \uacc4\ud68d",B.a06,B.z)
B.ZF=s(["\ubcf8\uc778\uc740 \uae4a\uc740 \uc218\uc2ec, \uc758\ubb34 \uac10\uc555 \ub610\ub294 \ud2b9\uc218\ud55c \uc218\uc911 \ud658\uacbd\uc5d0\uc11c \uc989\uac01\uc801\uc778 \uc218\uba74 \ubcf5\uadc0\uac00 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ub3d9\uad74, \ub09c\ud30c\uc120 \ub0b4\ubd80 \ub4f1 \ucc9c\uc7a5 \ud3d0\uc1c4 \ud658\uacbd\uc5d0\uc11c\uc758 \ub2e4\uc774\ube59\uc740 \ucd94\uac00\uc801\uc778 \uc804\ubb38 \uad50\uc721, \uc790\uaca9, \uc7a5\ube44 \ubc0f \uc548\uc804\uacc4\ud68d\uc744 \ud544\uc694\ub85c \ud558\uba70, \ud574\ub2f9 \uad50\uc721\uacfc\uc815\uc758 \ud5c8\uc6a9 \ubc94\uc704 \ub0b4\uc5d0\uc11c\ub9cc \uc218\ud589\ud574\uc57c \ud568\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc774\ub7ec\ud55c \ud658\uacbd\uc5d0\uc11c \ubc1c\uc0dd\ud558\ub294 \ube44\uc0c1\uc0c1\ud669\uc774 \uc77c\ubc18\uc801\uc778 \uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59\ubcf4\ub2e4 \ubcf5\uc7a1\ud55c \ub300\uc751\uc744 \uc694\uad6c\ud560 \uc218 \uc788\uc74c\uc744 \uc778\uc9c0\ud569\ub2c8\ub2e4."],t.s)
B.am5=new A.dZ("\uc81c6\uc870. \ud2b9\uc218 \ud658\uacbd\uacfc \uc218\uba74 \ubcf5\uadc0\uc758 \uc81c\ud55c",B.ZF,B.z)
B.Yh=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc774 \ub192\uc740 \uc218\uc900\uc758 \uc2e0\uccb4\uc801\xb7\uc815\uc2e0\uc801 \uc900\ube44\ub97c \uc694\uad6c\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uac74\uac15\uc9c4\uc220\uc11c\uc5d0 \uc815\ud655\ud558\uac8c \uc751\ub2f5\ud558\uace0 \ud544\uc694\ud55c \uacbd\uc6b0 \uc758\ub8cc\uc804\ubb38\uac00\uc758 \ud3c9\uac00\ub97c \ubc1b\uaca0\uc2b5\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uac74\uac15 \uc0c1\ud0dc, \ud53c\ub85c \ub610\ub294 \uc2ec\ub9ac\uc801 \uc2a4\ud2b8\ub808\uc2a4 \ub4f1\uc73c\ub85c \uc548\uc804\ud55c \ub2e4\uc774\ube59\uc774 \uc5b4\ub835\ub2e4\uace0 \ud310\ub2e8\ub418\ub294 \uacbd\uc6b0 \uc774\ub97c \uc989\uc2dc \uc54c\ub9ac\uace0 \ud65c\ub3d9\uc744 \uc911\ub2e8\ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.alV=new A.dZ("\uc81c7\uc870. \uac74\uac15 \uc0c1\ud0dc \ubc0f \uc2e0\uccb4\uc801 \uc900\ube44",B.Yh,B.z)
B.a_x=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc5d0\uc11c \ud300\uc6d0 \uac04\uc758 \ud611\ub825, \uc758\uc0ac\uc18c\ud1b5 \ubc0f \uc0c1\ud638 \uc548\uc804 \ud655\uc778\uc774 \uc911\uc694\ud568\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \ub2e4\uc74c \uc0ac\ud56d\uc744 \uc900\uc218\ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.a0b=s(["\ub2f4\ub2f9 \uac15\uc0ac\uc640 \ud300\uc6d0\uc774 \uacf5\uc720\ud55c \ub2e4\uc774\ube59 \uacc4\ud68d\uc744 \uc900\uc218\ud569\ub2c8\ub2e4.","\ub2e4\uc774\ube59 \uc804 \uc7a5\ube44 \ubc0f \ud638\ud761 \uae30\uccb4 \ud655\uc778 \uc808\ucc28\uc5d0 \ucc38\uc5ec\ud569\ub2c8\ub2e4.","\uacc4\ud68d\ub41c \ud300 \uad6c\uc131\uacfc \uc218\uc911 \uc758\uc0ac\uc18c\ud1b5 \uccb4\uacc4\ub97c \uc900\uc218\ud569\ub2c8\ub2e4.","\uc7a5\ube44 \uc774\uc0c1 \ub610\ub294 \uc704\ud5d8\uc0c1\ud669 \ubc1c\uc0dd \uc2dc \uc989\uc2dc \ud300\uc6d0\uacfc \uac15\uc0ac\uc5d0\uac8c \uc54c\ub9bd\ub2c8\ub2e4.","\uac1c\uc778\uc758 \ud310\ub2e8\uc73c\ub85c \uad50\uc721\ubc94\uc704 \ub610\ub294 \ub2e4\uc774\ube59 \uacc4\ud68d\uc744 \ud655\ub300\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uc548\uc804\uc0c1 \ud544\uc694\ud558\ub2e4\uace0 \ud310\ub2e8\ub418\ub294 \uacbd\uc6b0 \ub2e4\uc774\ube59 \uc911\ub2e8\uc744 \uc694\uccad\ud569\ub2c8\ub2e4."],t.s)
B.amk=new A.dZ("\uc81c8\uc870. \ud300 \ub2e4\uc774\ube59 \ubc0f \uc548\uc804\uc9c0\uce68 \uc900\uc218",B.a_x,B.a0b)
B.Y5=s(["\ubcf8\uc778\uc740 APDI\uac00 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59 \uad50\uc721 \uae30\uc900 \ubc0f \uad50\uc721\uccb4\uacc4\ub97c \uc81c\uacf5\ud558\ub294 \uc804\ubb38\ub2e8\uccb4\uc774\uba70, \uac1c\ubcc4 \uac15\uc0ac\uc640 \uad50\uc721\uae30\uad00\uc774 \ub3c5\ub9bd\uc801\uc73c\ub85c \ud65c\ub3d9\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ub2e4\ub9cc APDI, \uad50\uc721\uae30\uad00, \uac15\uc0ac \ubc0f \uad00\ub828\uc790\uc758 \uad6c\uccb4\uc801\uc778 \ubc95\uc801 \ucc45\uc784\uc740 \uc2e4\uc81c \uacc4\uc57d\uad00\uacc4, \uad50\uc721 \uc6b4\uc601 \ubc0f \uad00\ub9ac\xb7\uac10\ub3c5\uad00\uacc4\uc640 \uad00\ub828 \ubc95\ub839\uc5d0 \ub530\ub77c \ud310\ub2e8\ub428\uc744 \uc774\ud574\ud569\ub2c8\ub2e4."],t.s)
B.am0=new A.dZ("\uc81c9\uc870. \uad50\uc721\uae30\uad00\uacfc APDI\uc758 \uad00\uacc4",B.Y5,B.z)
B.a09=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc758 \uace0\uc720\ud55c \uc704\ud5d8\uacfc \uc77c\ubc18\uc801\uc778 \uc2a4\ucfe0\ubc84\ub2e4\uc774\ube59\ubcf4\ub2e4 \ub192\uc744 \uc218 \uc788\ub294 \uc704\ud5d8 \uc218\uc900\uc5d0 \ub300\ud55c \uc124\uba85\uc744 \ucda9\ubd84\ud788 \ub4e4\uc5c8\uc73c\uba70, \uc774\ub97c \uc774\ud574\ud55c \uc0c1\ud0dc\uc5d0\uc11c \uc790\ubc1c\uc801\uc73c\ub85c \ucc38\uac00\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc801\uc808\ud55c \uad50\uc721, \uc7a5\ube44 \ubc0f \uc548\uc804\uc808\ucc28\uac00 \uc81c\uacf5\ub418\ub354\ub77c\ub3c4 \ubaa8\ub4e0 \uc7a0\uc7ac\uc801 \uc704\ud5d8\uc774 \uc81c\uac70\ub418\uc9c0\ub294 \uc54a\ub294\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc778\uc815\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc790\uc2e0\uc758 \uc790\uaca9, \uacbd\ud5d8 \ubc0f \uc2e0\uccb4\uc801 \ub2a5\ub825\uc758 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uad50\uc721 \ubc0f \ud6c8\ub828\uc5d0 \ucc38\uac00\ud558\uaca0\uc2b5\ub2c8\ub2e4."],t.s)
B.ama=new A.dZ("\uc81c10\uc870. \uc790\ubc1c\uc801 \ucc38\uac00 \ubc0f \uc704\ud5d8 \uc218\uc6a9",B.a09,B.z)
B.a01=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59\uc5d0 \uc218\ubc18\ub418\ub294 \ubcf8\uc9c8\uc801\uc778 \uc704\ud5d8\uc744 \uc778\uc9c0\ud558\uace0 \uad00\uacc4 \ubc95\ub839\uc5d0\uc11c \ud5c8\uc6a9\ud558\ub294 \ubc94\uc704 \ub0b4\uc5d0\uc11c \uc774\ub7ec\ud55c \uc704\ud5d8\uc758 \ubc1c\uc0dd \uac00\ub2a5\uc131\uc744 \uc218\uc6a9\ud569\ub2c8\ub2e4.","\uadf8\ub7ec\ub098 \ubcf8 \ub3d9\uc758\uc11c\ub294 APDI, \uad50\uc721\uae30\uad00, \ub2f4\ub2f9 \uac15\uc0ac \ub610\ub294 \uad00\ub828\uc790\uc758 \uace0\uc758\xb7\uacfc\uc2e4\uc5d0 \ub530\ub978 \ubc95\uc801 \ucc45\uc784\uc744 \uc77c\uad04\uc801\uc73c\ub85c \uba74\uc81c\ud558\uac70\ub098 \ucc38\uac00\uc790\uc758 \uc815\ub2f9\ud55c \ubc95\uc801 \uad8c\ub9ac\ub97c \ud3ec\uad04\uc801\uc73c\ub85c \ud3ec\uae30\ud558\ub294 \uac83\uc73c\ub85c \ud574\uc11d\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.","\uc0ac\uace0\uc5d0 \ub300\ud55c \ucc45\uc784\uc758 \uc720\ubb34\uc640 \ubc94\uc704\ub294 \uad6c\uccb4\uc801\uc778 \uc0ac\uc2e4\uad00\uacc4 \ubc0f \uad00\ub828 \ubc95\ub839\uc5d0 \ub530\ub77c \ud310\ub2e8\ub429\ub2c8\ub2e4."],t.s)
B.am2=new A.dZ("\uc81c11\uc870. \ucc45\uc784 \uba74\ucc45\uc758 \ubc94\uc704",B.a01,B.z)
B.a_a=s(["\ubcf8\uc778\uc740 \ud14c\ud06c\ub2c8\uceec \ub2e4\uc774\ube59 \uc0ac\uace0\uac00 \ubc1c\uc0dd\ud558\ub294 \uc7a5\uc18c\uc640 \ud658\uacbd\uc5d0 \ub530\ub77c \uad6c\uc870, \uc758\ub8cc\uae30\uad00 \uc774\uc1a1 \ubc0f \uc804\ubb38 \uc7a0\uc218\uc758\ud559\uc801 \uce58\ub8cc\uac00 \uc9c0\uc5f0\ub420 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud569\ub2c8\ub2e4.","\ubcf8\uc778\uc740 \uc751\uae09\uc0c1\ud669 \ubc1c\uc0dd \uc2dc \uad50\uc721\uae30\uad00 \ub610\ub294 \uad6c\uc870 \ub2f4\ub2f9\uc790\uac00 \ud544\uc694\ud55c \uad6c\uc870 \uc694\uccad, \uc751\uae09\ucc98\uce58 \ubc0f \uc758\ub8cc\uae30\uad00 \uc774\uc1a1\uc744 \uc704\ud55c \uc870\uce58\ub97c \ucde8\ud560 \uc218 \uc788\uc74c\uc744 \uc774\ud574\ud558\uace0 \uc774\uc5d0 \ub3d9\uc758\ud569\ub2c8\ub2e4."],t.s)
